{
"code": "#note-form {
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

#note {
  font-family: inherit;
  font-size: inherit;
  line-height: inherit;
  padding: var(--space-md);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  background-color: var(--color-surface);
  resize: vertical;
}

#note:focus {
  outline: none;
  border-color: var(--color-accent);
  box-shadow: 0 0 0 3px var(--color-focus-ring);
}

#note-form button[type="submit"] {
  align-self: flex-start;
  padding: var(--space-sm) var(--space-lg);
  font-size: 14px;
  font-weight: 600;
  color: var(--color-accent);
  background-color: transparent;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-sm);
  cursor: pointer;
}

#note-form button[type="submit"]:hover {
  background-color: rgba(0, 95, 107, 0.05);
  border-color: var(--color-accent);
}

#note-form button[type="submit"]:focus {
  outline: none;
  box-shadow: 0 0 0 3px var(--color-focus-ring);
}

.hidden {
  display: none !important;
}

.nav-lesson-btn[aria-current="true"] {
  background-color: rgba(224, 122, 95, 0.1);
  color: var(--color-current);
  font-weight: 700;
  border-left: 3px solid var(--color-current);
}

@media (prefers-reduced-motion: reduce) {
  * {
    transition-duration: 0s !important;
  }
}

@media (max-width: 1440px) {
  .app-layout {
    grid-template-columns: 240px 1fr;
  }
}

@media (max-width: 390px) {
  .app-header {
    flex-direction: column;
    align-items: stretch;
    padding: var(--space-md);
    gap: var(--space-sm);
  }

  #search-form {
    width: 100%;
  }

  #search {
    width: 100%;
  }

  .app-layout {
    grid-template-columns: 1fr;
    padding: var(--space-md);
    gap: var(--space-lg);
  }

  #course-nav {
    flex-direction: row;
    overflow-x: auto;
    padding-bottom: var(--space-sm);
    -webkit-overflow-scrolling: touch;
  }

  .nav-weeks {
    display: flex;
    gap: var(--space-md);
    min-width: max-content;
  }

  .nav-week {
    display: inline-flex;
    flex-direction: column;
    gap: var(--space-xs);
    min-width: 120px;
  }

  .week-title {
    padding-left: 0;
    font-size: 12px;
  }

  #lesson-title {
    font-size: 24px;
  }

  #lesson-content {
    font-size: 16px;
  }

  #complete {
    width: 100%;
    text-align: center;
  }
}

@media (max-width: 320px) {
  .app-header h1 {
    font-size: 20px;
  }

  #lesson-title {
    font-size: 22px;
  }

  .nav-week {
    min-width: 100px;
  }
}
"
}
